import React, { useEffect, useState } from "react";
import { useLocation } from "react-router-dom";
import SidebarMenu from "./SidebarMenu";

const Layout = ({ children }) => {
  const location = useLocation();
  const hideSidebar = location.pathname.startsWith("/auth/login") || location.pathname === "/";
  const [module, setModule] = useState("");

  useEffect(() => {
    // Determine current module based on URL
    const path = location.pathname.split("/")[1]; // e.g., 'journal'
    setModule(path);
  }, [location.pathname]);

  // Initialize AdminLTE components
  useEffect(() => {
    // Load AdminLTE JS if not loaded
    if (!window.$ || !window.$.fn.treeview) {
      // You can load AdminLTE JS here if needed
      console.log("AdminLTE JS not loaded");
    } else {
      // Initialize treeview for sidebar
      $('[data-widget="treeview"]').treeview();
      
      // Initialize pushmenu for sidebar toggle
      $('[data-widget="pushmenu"]').pushmenu();
    }

    // Fallback manual toggle if AdminLTE JS is not available
    const pushMenuButtons = document.querySelectorAll('[data-widget="pushmenu"]');
    pushMenuButtons.forEach(button => {
      button.addEventListener('click', function(e) {
        e.preventDefault();
        const body = document.body;
        
        // Toggle sidebar classes
        if (body.classList.contains('sidebar-collapse') || 
            body.classList.contains('sidebar-open')) {
          body.classList.remove('sidebar-collapse');
          body.classList.remove('sidebar-open');
        } else {
          body.classList.add('sidebar-collapse');
        }
      });
    });

    return () => {
      // Cleanup event listeners
      const pushMenuButtons = document.querySelectorAll('[data-widget="pushmenu"]');
      pushMenuButtons.forEach(button => {
        button.replaceWith(button.cloneNode(true));
      });
    };
  }, []);

  return (
    <div className="wrapper hold-transition sidebar-mini layout-fixed">
      
      {!hideSidebar && (
        <nav className="main-header navbar navbar-expand navbar-white navbar-light">
          <ul className="navbar-nav">
            <li className="nav-item">
              <a 
                className="nav-link" 
                data-widget="pushmenu" 
                href="#" 
                role="button"
                onClick={(e) => {
                  e.preventDefault();
                  const body = document.body;
                  
                  // Simple toggle without AdminLTE JS
                  if (body.classList.contains('sidebar-collapse') || 
                      body.classList.contains('sidebar-open')) {
                    body.classList.remove('sidebar-collapse');
                    body.classList.remove('sidebar-open');
                  } else {
                    body.classList.add('sidebar-collapse');
                  }
                }}
              >
                <i className="fas fa-bars"></i>
              </a>
            </li>
          </ul>
        </nav>
      )}

      {!hideSidebar && <SidebarMenu module={module} />}

      <div className="content-wrapper p-3">
        <section className="content container-fluid">{children}</section>
      </div>
    </div>
  );
};

export default Layout;
